{"tool":"write","path":"reports/export.py","content":""""RFC 4180 CSV exporter for report rows."""

__all__ = ["export_csv"]


def export_csv(rows, columns):
    """Export mappings as RFC 4180 CSV text, including the header.

    rows is an iterable of mappings; columns is an ordered iterable of unique
    string column names. Returns a str with comma delimiters, CRLF record
    endings, minimal quoting, and doubled quotes.
    """
    names = list(columns)  # materialize once; supports one-shot generators
    seen = set()
    for name in names:
        if not isinstance(name, str):
            raise ValueError("column names must be strings: {!r}".format(name))
        if name in seen:
            raise ValueError("duplicate column name: {!r}".format(name))
        seen.add(name)

    chunks = []
    chunks.append(",".join(_field(name) for name in names))
    for row in rows:
        chunks.append(",".join(_field(row.get(name)) for name in names))
    return "\r\n".join(chunks) + "\r\n"


def _field(value):
    if value is None:
        return ""
    text = value if isinstance(value, str) else str(value)
    if any(c in text for c in ("\r", "\n", '"', ",")):
        return '"' + text.replace('"', '""') + '"'
    return text
